        const query = String(args.query || "");
        if (!query) return observe({ error: "search requires args.query" });
        const base = inside(root, args.path || "."), relativePath = relative(root, base);
        if (relativePath !== "" && !readAdmitted(relativePath)) return observe({ error: "structured refusal" });
        const hits = [];
        for (const file of walk(root, base, [], 600)) {
